      "old": "        // ---- P4M tracking ----
        // Lane state is maintained continuously from reset (warmup, window, drain) so that a job
        // issued strictly before the opening edge is visible as a carry cohort. Error evidence is
        // only recorded between ARM and the closing boundary, so the frozen bank cannot move.
        p4m_track_err = p4m_q && !p4m_closed_q;
        v_issue_evt = P4MEnable && issue_i[victim_q];
        v_done_evt = P4MEnable && done_i[victim_q];
