                if (p4m_track_err && issue_id_i[victim_q] == 0) p4m_error_n[0] = 1'b1;
                if (p4m_track_err && v_task_n) p4m_error_n[2] = 1'b1;
                v_task_n = 1'b1;
                v_id_n = issue_id_i[victim_q];
            end
            if (has_a_q) begin
                if (a_done_evt) begin
                    if (p4m_track_err && (!a_task_q || done_id_i[aggressor_q] != a_id_q)) p4m_error_n[1] = 1'b1;
